function rollRaceGenome(race){const r=races[race],stats={},caps={};Object.keys(statNames).forEach(k=>{const base=r.base[k],cap=r.caps[k];const statSpread=Math.max(2,Math.round(base*.18));stats[k]=clamp(base+rnd(-statSpread,statSpread),1,cap);caps[k]=k==='charisma'?100:Math.max(stats[k],rnd(base,cap));});return {stats,caps}}
function applyChaosMercy(stats,caps){if(Math.random()>=.01)return null;const keys=Object.keys(statNames),fav=pick(keys.filter(k=>k!=='charisma')),weak=pick(keys.filter(k=>k!==fav));caps[fav]=Math.max(stats[fav],Math.round(caps[fav]*2));caps[weak]=Math.max(1,Math.round(caps[weak]*.5));stats[weak]=Math.min(stats[weak],caps[weak]);return {fav,weak}}
function applyAzerothCurse(stats,caps){if(Math.random()>=.005)return null;const keys=Object.keys(statNames),fav=pick(keys.filter(k=>k!=='charisma')),weak=pick(keys.filter(k=>k!==fav));caps[fav]=Math.max(stats[fav],Math.round(caps[fav]*3));caps[weak]=Math.max(1,Math.round(caps[weak]*.5));stats[weak]=Math.min(stats[weak],caps[weak]);return {fav,weak}}
function normalizeAzerothCurse(curse,caps,stats){if(!curse||typeof curse!=='object'||!statNames[curse.fav]||!statNames[curse.weak]||curse.fav===curse.weak)return null;return {fav:curse.fav,weak:curse.weak}}
