function newHero(){eventQueue=[];battle=null;if($('overlay'))$('overlay').style.display='none';let race=$('race').value,r=races[race],genome=pendingGenome&&pendingGenomeRace===race?pendingGenome:rollRaceGenome(race),stats=genome.stats,caps=genome.caps;pendingGenome=null;pendingGenomeRace=null;let b=blessings[fate.blessing],c=curses[fate.curse];applyMap(caps,b[2]);applyMap(caps,c[2]);Object.keys(caps).forEach(k=>caps[k]=Math.max(1,caps[k]));applyMap(stats,b[3]);applyMap(stats,c[3]);Object.keys(stats).forEach(k=>{caps[k]=Math.max(1,caps[k],stats[k]);stats[k]=clamp(stats[k],1,caps[k])});let chaosMercy=applyChaosMercy(stats,caps),azarothCurse=applyAzerothCurse(stats,caps);s={name:($('heroName').value.trim().slice(0,24).replace(/[<>]/g,''))||'Безымянный',race,age:0,worldYear:1453,year:0,gold:100,rep:100,glory:0,gloryKillCounts:{},strongestChallenges:{arden:false,seraphina:false,kael:false},titles:[],titleBonuses:{},kills:{},milestones:{},azerothDefeated:false,azerothAwakened:false,lastAzerothDreamYear:-1,azerothDeals:{},azerothRefusals:0,azerothDebt:0,saintKnightDefeated:false,stats,caps,capTraining:{},hp:stats.health,mana:stats.mana,stamina:stats.stamina,stress:0,actions:1,blessing:fate.blessing,curse:fate.curse,chaosMercy,azarothCurse,legendaryDefeated:{arden:false,seraphina:false,kael:false},phoenix:b[4]==='phoenix',phoenixAmulet:false,fury:c[4]==='fury',thirst:c[4]==='thirst',restless:c[4]==='restless',children:[],spouse:null,log:[],quest:{progress:0,done:false,unlocked:false},gear:{armor:0,sword:0,staff:0},artifact:false,artifacts:[],school:{sword:null,magic:null,tech:[],training:0,swordTraining:0,magicTraining:0,swordDamage:0,healthBonus:0},outcast:false,holyAttack:0,house:0,shopArtifact:null,stressPenalty:false,portrait:race,ritualUnlocked:false,adventureEvent:false,worldCharacters:[],worldInitialized:false,kingdoms:null,kingdomRelations:null,kingdomMilestones:{},worldState:null,relationships:[],injuries:[],cursedAmulets:[],equippedCursedAmulet:null,ruins:null,legacy:null,dynastyHistory:[],rivalHistory:[],worldEventHistory:[],npcDuelWins:{}};ensureLivingWorld();s.hp=maxHP();log('Летопись начинается. '+r.name+' вступает в свой путь. Генетическая лотерея определила индивидуальные стартовые показатели и пределы.'+(chaosMercy?` Милость бога Хаоса: предел ${statNames[chaosMercy.fav]} удвоен, предел ${statNames[chaosMercy.weak]} уменьшен вдвое.`:'')+(azarothCurse?` Проклятие Азарота: предел ${statNames[azarothCurse.fav]} утроен, предел ${statNames[azarothCurse.weak]} уменьшен вдвое.`:''));$('setup').classList.add('hidden');$('game').classList.remove('hidden');$('dock').classList.remove('hidden');render()}
