function changeRep(delta,reason='поступок'){let before=s.rep;let adjusted=delta;if(delta>0){if(before>=160)adjusted=Math.max(1,Math.round(delta*.25));else if(before>=120)adjusted=Math.max(1,Math.round(delta*.5))}s.rep=clamp(Math.round((Number.isFinite(Number(s.rep))?Number(s.rep):100)+adjusted),0,200);if(s.rep!==before){log(`Репутация ${delta>0?'+':''}${s.rep-before} (${reason}). Теперь: ${s.rep}/200 — ${repName()}.`);checkTitles()}}
