function awardTitle(id){s.titles=s.titles||[];s.titleBonuses=s.titleBonuses||{};let def=titleDefs.find(t=>t.id===id);if(!def||s.titles.includes(id))return false;s.titles.push(id);Object.entries(def.bonus).forEach(([k,v])=>s.titleBonuses[k]=(s.titleBonuses[k]||0)+v);log(`Получен титул «${def.name}»! Бонусы: ${Object.entries(def.bonus).map(([k,v])=>`${statNames[k]} +${v}`).join(', ')}.`);addGlory(['arden','seraphina','kael','azaroth','saint'].includes(id)?50:10,'получение титула «'+def.name+'»');playSound('success');return true}
