function companionBonus(k){return (s?.companions||[]).filter(c=>c&&c.active!==false).reduce((n,c)=>n+Number(c.bonus?.[k]||0),0)}
function statWithTitles(k){let v=(Number(s.stats[k])||0)+(Number(s.titleBonuses?.[k])||0)+companionBonus(k);(s.injuries||[]).forEach(x=>{v+=Number(x.mods?.[k]||0)});if(s.equippedCursedAmulet){let a=(s.cursedAmulets||[]).find(x=>x.id===s.equippedCursedAmulet);if(a)v+=Number(a.mods?.[k]||0)}return Math.max(1,v)}
