function awakenAzeroth(source='мир'){if(!s)return;s.azerothAwakened=true;s.worldState=s.worldState||{};if(!s.worldState.demonicInvasion){s.worldState.demonicInvasion=true;s.worldState.demonicPressure=1;worldNews(`Появление Азарота раскололо небеса. Демоны начали проникать в Эйрвальд; вести о первых нападениях дошли до всех государств.`);Object.values(s.kingdoms||{}).forEach(k=>{k.stability=clamp(k.stability-5,10,100)});log('Началось демоническое вторжение. Демоны теперь могут появляться в событиях, приключениях и на охоте.')}return true}
function rollDemon(){if(!s?.azerothAwakened)return null;let pool=demonRanks.flatMap(d=>Array(d.chance).fill(d));let d=pick(pool),mod=pick([-.1,0,.1]),power=Math.max(15,Math.round(d.base*(1+mod)));return {name:d.name,tier:d.tier,power,hp:Math.round(power*2.15),mod,demon:true,desc:'Демон, проникший в мир после пробуждения Азарота.'}}
function encounterDemon(source){if(!s?.azerothAwakened||battle||$('overlay').style.display==='flex')return false;let e=rollDemon();if(!e)return false;log(`Демоническое вторжение: ${e.name} (сила ${e.power}) обнаружен ${source}.`);worldNews(`В районе ${pick(['пограничных деревень','старого тракта','лесных поселений','торгового пути','окрестностей столицы'])} замечен ${e.name.toLowerCase()}. Жители укрываются, стража собирает ополчение.`);return startBattle(e)}
