function marryWorldPerson(id){let n=findWorldPerson(id);if(!n||s.dead||battle||$('overlay').style.display==='flex'||s.age<18||n.age<18){alert('Оба персонажа должны быть совершеннолетними.');return}if(s.spouse){alert('У вас уже есть супруг(а).');return}let rel=n.relations||{};if((rel.affection||0)<18){alert('Сначала нужно развить романтическую привязанность.');return}if(Number(n.lastInteractionYear)===Number(s.worldYear)){alert('С этим персонажем вы уже взаимодействовали в этом году.');return}if(!spend())return;n.lastInteractionYear=s.worldYear;s.spouse={npcId:id,name:n.name,race:n.race,age:n.age,stats:{...n.stats},caps:{...n.caps}};if(!s.relationships.some(x=>x.id===id&&x.type==='супруг(а)'))s.relationships.push({id,type:'супруг(а)',since:s.worldYear});log(`Вы заключили союз с ${n.name}. Его/её генетика будет участвовать в наследовании.`);render()}
