  s.worldYear=Number.isFinite(Number(s.worldYear))?Number(s.worldYear):1453;s.stats={...races[s.race].base,...s.stats};s.caps={...races[s.race].caps,...s.caps};const preserveAgingCaps=!s.outcast&&Number(s.age||0)>=races[s.race].life;Object.keys(statNames).forEach(k=>{const cap=Number(s.caps[k]);s.caps[k]=Number.isFinite(cap)&&cap>0?cap:races[s.race].caps[k];if(k==='charisma')s.caps[k]=Math.min(100,s.caps[k]);const value=Number(s.stats[k]);if(!preserveAgingCaps&&k!=='charisma'&&Number.isFinite(value))s.caps[k]=Math.max(s.caps[k],value);s.stats[k]=clamp(Number.isFinite(value)?value:races[s.race].base[k],1,Math.max(1,s.caps[k]))});
  s.capTraining=s.capTraining&&typeof s.capTraining==='object'?s.capTraining:{};Object.keys(statNames).forEach(k=>s.capTraining[k]=clamp(Math.floor(Number(s.capTraining[k])||0),0,4));s.school=s.school&&typeof s.school==='object'?s.school:{sword:null,magic:null,tech:[]};s.school.sword=['fire','stone'].includes(s.school.sword)?s.school.sword:null;s.school.magic=['light','chaos'].includes(s.school.magic)?s.school.magic:null;s.school.tech=Array.isArray(s.school.tech)?s.school.tech.filter(x=>typeof x==='string'):[];s.school.swordTraining=s.school.swordTraining||0;s.school.magicTraining=s.school.magicTraining||0;s.school.swordDamage=s.school.swordDamage||0;s.school.healthBonus=s.school.healthBonus||0;
